// ---------- CONFIG ----------
// Google Docs whose title contains any of these words are treated as meeting notes.
const NAME_KEYWORDS = ['Notes', 'Transcript', 'Minutes'];
const FIRST_RUN_LOOKBACK_HOURS = 24;   // on the very first run, only look this far back
const OVERLAP_MINUTES = 30;            // re-check a little before the last run to avoid gaps
// ----------------------------

const state = $getWorkflowStaticData('global');
const since = state.lastCheck
  ? DateTime.fromISO(state.lastCheck).minus({ minutes: OVERLAP_MINUTES })
  : $now.minus({ hours: FIRST_RUN_LOOKBACK_HOURS });

const esc = (s) => String(s).replace(/\\/g, '\\\\').replace(/'/g, "\\'");
const nameClause = NAME_KEYWORDS.map(k => `name contains '${esc(k)}'`).join(' or ');
const q = [
  "mimeType='application/vnd.google-apps.document'",
  'trashed=false',
  `(${nameClause})`,
  `modifiedTime > '${since.toUTC().toISO({ suppressMilliseconds: true })}'`,
].join(' and ');

return [{ json: { q, checkedAt: $now.toUTC().toISO() } }];

// Processes ONE new notes doc per run (runs every 15 min), which keeps item pairing simple.
const MAX_REMEMBERED = 500;

const state = $getWorkflowStaticData('global');
state.processed = state.processed || {};

const files = ($input.first().json.files || []);
const next = files.find(f => f && f.id && !state.processed[f.id]);

if (!next) {
  // Nothing left in this window -> move the window forward.
  state.lastCheck = $('Find Window').first().json.checkedAt;
  const ids = Object.keys(state.processed);
  if (ids.length > MAX_REMEMBERED) {
    ids.sort((a, b) => String(state.processed[a]).localeCompare(String(state.processed[b])));
    for (const id of ids.slice(0, ids.length - MAX_REMEMBERED)) delete state.processed[id];
  }
  return [];
}

return [{ json: { id: next.id, name: next.name, webViewLink: next.webViewLink || `https://docs.google.com/document/d/${next.id}/edit`, modifiedTime: next.modifiedTime } }];

// ---------- CONFIG ----------
const GEMINI_MODEL = 'gemini-2.5-flash';
const EXEC_NAME = 'Marvin';
const TZ = 'Asia/Manila';
const MAX_NOTE_CHARS = 60000;   // keeps token usage in check on long transcripts
const MIN_NOTE_CHARS = 50;      // ignore empty / placeholder docs
const IGNORE_EMAILS = [];       // e.g. ['you@yourdomain.com'] -> never added as a recap recipient
// ----------------------------

const doc = $('Pick Next Doc').first().json;
let notes = String($json.text ?? $json.data ?? '').replace(/\r/g, '').trim();

if (notes.length < MIN_NOTE_CHARS) {
  const state = $getWorkflowStaticData('global');
  state.processed = state.processed || {};
  state.processed[doc.id] = $now.toUTC().toISO();
  return [];
}
if (notes.length > MAX_NOTE_CHARS) notes = notes.slice(0, MAX_NOTE_CHARS) + '\n[...truncated]';

// Recipients come only from addresses literally written in the notes (never guessed by the AI).
const ignore = new Set(IGNORE_EMAILS.map(e => e.toLowerCase()));
const attendees = [...new Set((notes.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g) || [])
  .map(e => e.toLowerCase()))].filter(e => !ignore.has(e)).slice(0, 20);

const today = $now.setZone(TZ).toISODate();
const prompt = `You are an executive assistant for ${EXEC_NAME}. Today is ${today} (${TZ}).
Read the meeting notes or transcript below and extract:
- meeting_title: a short, specific title for the meeting
- summary: 2-4 sentences on what was discussed and why it matters
- decisions: decisions that were actually made (empty list if none)
- action_items: each with
    task: one clear task starting with a verb
    owner: the person responsible, or "Unassigned" if nobody was named
    due_date: YYYY-MM-DD; resolve relative dates such as "next Friday" from today; null if no date was stated
    priority: high, medium or low
Only include action items that were clearly assigned or agreed. Never invent owners, dates or tasks.

Document title: ${doc.name}
---
${notes}`;

const schema = {
  type: 'OBJECT',
  properties: {
    meeting_title: { type: 'STRING' },
    summary: { type: 'STRING' },
    decisions: { type: 'ARRAY', items: { type: 'STRING' } },
    action_items: {
      type: 'ARRAY',
      items: {
        type: 'OBJECT',
        properties: {
          task: { type: 'STRING' },
          owner: { type: 'STRING' },
          due_date: { type: 'STRING', nullable: true },
          priority: { type: 'STRING', enum: ['high', 'medium', 'low'] },
        },
        required: ['task', 'owner', 'priority'],
      },
    },
  },
  required: ['meeting_title', 'summary', 'decisions', 'action_items'],
};

return [{
  json: {
    geminiModel: GEMINI_MODEL,
    geminiBody: {
      contents: [{ role: 'user', parts: [{ text: prompt }] }],
      generationConfig: { temperature: 0.2, responseMimeType: 'application/json', responseSchema: schema },
    },
    docId: doc.id,
    docName: doc.name,
    docLink: doc.webViewLink,
    attendees,
    execName: EXEC_NAME,
  },
}];

// Defensive parsing of the Gemini response. Marks the doc as processed either way,
// so a doc that can't be parsed is flagged once in Slack instead of retried forever.
const ctx = $('Build Gemini Request').first().json;
const raw = $json;

let parsed = null;
let failReason = '';
try {
  const text = (raw?.candidates?.[0]?.content?.parts || []).map(p => p.text || '').join('').trim();
  if (!text) throw new Error(raw?.promptFeedback?.blockReason ? `blocked: ${raw.promptFeedback.blockReason}` : 'empty response');
  parsed = JSON.parse(text.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, ''));
} catch (e) {
  failReason = e.message;
}

const state = $getWorkflowStaticData('global');
state.processed = state.processed || {};
state.processed[ctx.docId] = $now.toUTC().toISO();

const p = parsed || {};
const clean = (s) => String(s ?? '').replace(/\s+/g, ' ').trim();
const actionItems = (Array.isArray(p.action_items) ? p.action_items : [])
  .filter(a => a && clean(a.task))
  .slice(0, 25)
  .map(a => ({
    task: clean(a.task),
    owner: clean(a.owner) || 'Unassigned',
    dueDate: /^\d{4}-\d{2}-\d{2}$/.test(clean(a.due_date)) ? clean(a.due_date) : null,
    priority: ['high', 'medium', 'low'].includes(clean(a.priority).toLowerCase()) ? clean(a.priority).toLowerCase() : 'medium',
  }));

return [{
  json: {
    ok: !!parsed,
    failReason,
    title: clean(p.meeting_title) || ctx.docName,
    summary: clean(p.summary),
    decisions: (Array.isArray(p.decisions) ? p.decisions : []).map(clean).filter(Boolean).slice(0, 15),
    actionItems,
    attendees: ctx.attendees,
    docName: ctx.docName,
    docLink: ctx.docLink,
    execName: ctx.execName,
  },
}];

// ---------- CONFIG ----------
const TRELLO_BOARD_ID = 'W7cGgwwY';   // board that receives the action-item cards
// ----------------------------

const m = $json;

// ----- Gmail draft (plain text, never sent automatically) -----
const lines = ['Hi all,', '', `Thanks for joining "${m.title}". Here's a quick recap.`, '', 'SUMMARY', m.summary || '(no summary)', ''];
if (m.decisions.length) {
  lines.push('DECISIONS');
  m.decisions.forEach(d => lines.push(`- ${d}`));
  lines.push('');
}
lines.push('ACTION ITEMS');
if (m.actionItems.length) {
  m.actionItems.forEach(a => lines.push(`- ${a.task} | Owner: ${a.owner}${a.dueDate ? ` | Due: ${a.dueDate}` : ''}`));
} else {
  lines.push('- None recorded');
}
lines.push('', 'Let me know if I missed anything.', '', 'Best,', m.execName);

const b64 = (s) => Buffer.from(s, 'utf8').toString('base64');
const subject = `Recap: ${m.title}`;
const headers = [
  m.attendees.length ? `To: ${m.attendees.join(', ')}` : null,
  `Subject: =?UTF-8?B?${b64(subject)}?=`,
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset="UTF-8"',
  'Content-Transfer-Encoding: base64',
].filter(Boolean);
const mime = headers.join('\r\n') + '\r\n\r\n' + b64(lines.join('\r\n'));
const raw = Buffer.from(mime, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');

// ----- Slack blocks -----
const esc = (s = '') => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const prio = { high: ':red_circle:', medium: ':large_orange_circle:', low: ':white_circle:' };
const itemsText = m.actionItems.length
  ? m.actionItems.map(a => `${prio[a.priority] || ''} *${esc(a.task)}* - ${esc(a.owner)}${a.dueDate ? ` (due ${a.dueDate})` : ''}`).join('\n')
  : '_No action items recorded._';

const blocks = [
  { type: 'header', text: { type: 'plain_text', text: `Recap: ${m.title}`.slice(0, 150) } },
  { type: 'section', text: { type: 'mrkdwn', text: esc(m.summary || '(no summary)').slice(0, 2900) } },
];
if (m.decisions.length) {
  blocks.push({ type: 'section', text: { type: 'mrkdwn', text: ('*Decisions*\n' + m.decisions.map(d => `- ${esc(d)}`).join('\n')).slice(0, 2900) } });
}
blocks.push({ type: 'section', text: { type: 'mrkdwn', text: (`*Action items (${m.actionItems.length})*\n` + itemsText).slice(0, 2900) } });
blocks.push({ type: 'context', elements: [{ type: 'mrkdwn', text: `<${m.docLink}|Open notes> - recap email saved to Gmail drafts${m.attendees.length ? ` for ${m.attendees.length} attendee(s)` : ''} - cards added to Trello` }] });

return [{ json: { raw, blocks, text: `Recap: ${m.title} - ${m.actionItems.length} action item(s)`, trelloBoardId: TRELLO_BOARD_ID } }];

// ---------- CONFIG ----------
// New cards go to the first open list whose name matches; otherwise the board's first list.
const LIST_NAME_MATCH = /^(to ?do|backlog|inbox|action items?|this week)$/i;
const DUE_TIME = 'T09:00:00+08:00';   // due dates land at 9:00 AM Manila time
// ----------------------------

const lists = $input.all().map(i => i.json).filter(l => l && l.id && !l.closed);
const list = lists.find(l => LIST_NAME_MATCH.test(String(l.name || '').trim())) || lists[0];
if (!list) throw new Error('No open lists found on the Trello board - check TRELLO_BOARD_ID in "Build Recap".');

const m = $('Parse Action Items').first().json;
return m.actionItems.map(a => {
  const body = {
    idList: list.id,
    name: a.owner && a.owner !== 'Unassigned' ? `${a.task} (${a.owner})` : a.task,
    desc: `From meeting: ${m.title}\nOwner: ${a.owner}\nPriority: ${a.priority}\n\nNotes: ${m.docLink}`,
    pos: a.priority === 'high' ? 'top' : 'bottom',
  };
  if (a.dueDate) body.due = `${a.dueDate}${DUE_TIME}`;
  return { json: { body } };
});
